styleCss:
#pomi-aftercare-page {
  font-family: Arial, Helvetica, sans-serif;
  color: #2b211d;
  background: #fffaf7;
  line-height: 1.6;
}

#pomi-aftercare-page * {
  box-sizing: border-box;
}

#pomi-aftercare-page .pomi-wrap {
  width: min(1120px, 92%);
  margin: 0 auto;
}

#pomi-aftercare-page .pomi-hero {
  padding: 76px 0 56px;
  background:
    radial-gradient(circle at top right, rgba(196, 142, 117, 0.25), transparent 35%),
    linear-gradient(135deg, #fff4ed 0%, #fffaf7 52%, #f3ded2 100%);
  border-radius: 0 0 34px 34px;
}

#pomi-aftercare-page .pomi-hero-grid {
  display: grid;
  grid-template-columns: 1.08fr 0.92fr;
  gap: 38px;
  align-items: center;
}

#pomi-aftercare-page .pomi-kicker {
  display: inline-block;
  padding: 8px 14px;
  background: #f1d8cc;
  color: #6e3f31;
  border-radius: 999px;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  margin-bottom: 18px;
}

#pomi-aftercare-page h1 {
  font-size: clamp(38px, 5vw, 64px);
  line-height: 1.05;
  margin: 0 0 18px;
  color: #2b211d;
}

#pomi-aftercare-page h2 {
  font-size: clamp(28px, 4vw, 42px);
  line-height: 1.15;
  margin: 0 0 16px;
  color: #2b211d;
}

#pomi-aftercare-page h3 {
  font-size: 22px;
  line-height: 1.25;
  margin: 0 0 10px;
  color: #2b211d;
}

#pomi-aftercare-page p {
  margin: 0 0 16px;
  font-size: 17px;
  color: #4b3c36;
}

#pomi-aftercare-page ul {
  margin: 0;
  padding-left: 20px;
  color: #4b3c36;
  font-size: 16px;
}

#pomi-aftercare-page li {
  margin-bottom: 8px;
}

#pomi-aftercare-page .pomi-lead {
  font-size: 20px;
  max-width: 720px;
  color: #4b3c36;
}

#pomi-aftercare-page .pomi-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 26px;
}

#pomi-aftercare-page .pomi-btn {
  display: inline-block;
  padding: 14px 22px;
  border-radius: 999px;
  text-decoration: none;
  font-weight: 700;
  font-size: 16px;
  transition: transform 0.2s ease, opacity 0.2s ease;
}

#pomi-aftercare-page .pomi-btn:hover {
  transform: translateY(-2px);
  opacity: 0.92;
}

#pomi-aftercare-page .pomi-btn-primary {
  background: #8f5a47;
  color: #ffffff;
}

#pomi-aftercare-page .pomi-btn-secondary {
  background: #ffffff;
  color: #8f5a47;
  border: 1px solid #d5b6a8;
}

#pomi-aftercare-page .pomi-hero-card {
  background: #ffffff;
  border: 1px solid #efd9cf;
  border-radius: 30px;
  padding: 28px;
  box-shadow: 0 18px 45px rgba(74, 50, 40, 0.12);
}

#pomi-aftercare-page .pomi-hero-card-inner {
  border-radius: 24px;
  background:
    radial-gradient(circle at 50% 42%, rgba(143, 90, 71, 0.14), transparent 34%),
    linear-gradient(135deg, #fff7f2, #f0d7cc);
  padding: 28px;
  text-align: center;
  border: 1px solid #e8cfc3;
}

#pomi-aftercare-page .pomi-hero-card svg {
  width: 100%;
  max-width: 320px;
  height: auto;
  margin: 0 auto 20px;
  display: block;
}

#pomi-aftercare-page .pomi-hero-card strong {
  display: block;
  font-size: 24px;
  color: #2b211d;
  margin-bottom: 8px;
}

#pomi-aftercare-page .pomi-section {
  padding: 64px 0;
}

#pomi-aftercare-page .pomi-section-light {
  background: #ffffff;
}

#pomi-aftercare-page .pomi-two-col {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 38px;
  align-items: start;
}

#pomi-aftercare-page .pomi-card-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
  margin-top: 28px;
}

#pomi-aftercare-page .pomi-card {
  background: #ffffff;
  border: 1px solid #efd9cf;
  border-radius: 24px;
  padding: 22px;
  box-shadow: 0 10px 28px rgba(74, 50, 40, 0.08);
}

#pomi-aftercare-page .pomi-card p {
  font-size: 15px;
  margin-bottom: 0;
}

#pomi-aftercare-page .pomi-note-box {
  background: #fff4ed;
  border: 1px solid #efd9cf;
  border-radius: 30px;
  padding: 30px;
  margin-top: 28px;
}

#pomi-aftercare-page .pomi-warning-box {
  background: #2b211d;
  color: #ffffff;
  border-radius: 30px;
  padding: 30px;
  margin-top: 28px;
}

#pomi-aftercare-page .pomi-warning-box h3,
#pomi-aftercare-page .pomi-warning-box p,
#pomi-aftercare-page .pomi-warning-box li {
  color: #ffffff;
}

#pomi-aftercare-page .pomi-note-box a,
#pomi-aftercare-page .pomi-text-link {
  color: #8f5a47;
  font-weight: 700;
  text-decoration: underline;
}

#pomi-aftercare-page .pomi-process {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 18px;
  margin-top: 28px;
}

#pomi-aftercare-page .pomi-step {
  background: #fffaf7;
  border: 1px solid #efd9cf;
  border-radius: 24px;
  padding: 24px;
}

#pomi-aftercare-page .pomi-step-number {
  width: 42px;
  height: 42px;
  border-radius: 50%;
  background: #8f5a47;
  color: #ffffff;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  margin-bottom: 16px;
}

#pomi-aftercare-page .pomi-wide-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 18px;
  margin-top: 28px;
}

#pomi-aftercare-page .pomi-wide-card {
  background: #ffffff;
  border: 1px solid #efd9cf;
  border-radius: 24px;
  padding: 24px;
  box-shadow: 0 10px 28px rgba(74, 50, 40, 0.08);
}

#pomi-aftercare-page .pomi-faq {
  display: grid;
  gap: 14px;
  margin-top: 26px;
}

#pomi-aftercare-page details {
  background: #ffffff;
  border: 1px solid #efd9cf;
  border-radius: 18px;
  padding: 18px 20px;
  box-shadow: 0 8px 22px rgba(74, 50, 40, 0.06);
}

#pomi-aftercare-page summary {
  cursor: pointer;
  font-weight: 800;
  color: #2b211d;
  font-size: 18px;
}

#pomi-aftercare-page details p {
  margin-top: 12px;
  margin-bottom: 0;
}

#pomi-aftercare-page .pomi-final {
  text-align: center;
  padding: 72px 0;
  background: #2b211d;
  color: #ffffff;
}

#pomi-aftercare-page .pomi-final h2,
#pomi-aftercare-page .pomi-final p {
  color: #ffffff;
}

#pomi-aftercare-page .pomi-final p {
  max-width: 760px;
  margin-left: auto;
  margin-right: auto;
}

@media (max-width: 900px) {
  #pomi-aftercare-page .pomi-hero-grid,
  #pomi-aftercare-page .pomi-two-col,
  #pomi-aftercare-page .pomi-wide-grid {
    grid-template-columns: 1fr;
  }

  #pomi-aftercare-page .pomi-card-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  #pomi-aftercare-page .pomi-process {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 560px) {
  #pomi-aftercare-page .pomi-hero {
    padding-top: 46px;
  }

  #pomi-aftercare-page .pomi-card-grid {
    grid-template-columns: 1fr;
  }

  #pomi-aftercare-page .pomi-actions {
    flex-direction: column;
  }

  #pomi-aftercare-page .pomi-btn {
    text-align: center;
    width: 100%;
  }
}
